import type { HTMLAttributes } from "react";
import { cx } from "../utils/cx";

/**
 * The studio page header: an eyebrow (where you are), an editorial title, one sentence on what the page is for, and the
 * page's siblings as quiet tabs. Server-compatible.
 *
 *   <PageHeader><PageEyebrow>Galleries</PageEyebrow><PageTitle>All galleries</PageTitle>
 *     <PageDescription>Client galleries and how they are delivered.</PageDescription>
 *     <PageTabs aria-label="Galleries pages"><PageTab href="/g" current>All</PageTab>...</PageTabs></PageHeader>
 */
export function PageHeader({ className, ...rest }: HTMLAttributes<HTMLElement>) {
  return <header {...rest} className={cx("hm-page-header", className)} />;
}

export function PageEyebrow({ className, ...rest }: HTMLAttributes<HTMLParagraphElement>) {
  return <p {...rest} className={cx("hm-eyebrow", className)} />;
}

export function PageTitle({
  as: Heading = "h1",
  className,
  ...rest
}: HTMLAttributes<HTMLHeadingElement> & {
  /** The heading level. Default `h1`; use a lower level when the header sits inside a section. */
  as?: "h1" | "h2" | "h3";
}) {
  return <Heading {...rest} className={cx("hm-page-title", className)} />;
}

export function PageDescription({ className, ...rest }: HTMLAttributes<HTMLParagraphElement>) {
  return <p {...rest} className={cx("hm-page-description", className)} />;
}

/** Actions aligned with the title (a primary button, a menu). */
export function PageActions({ className, ...rest }: HTMLAttributes<HTMLDivElement>) {
  return <div {...rest} className={cx("hm-page-actions", className)} />;
}
